ontent.cgi?article=9542&context=doctoral", "source": {"id": "https://openalex.org/S4306400581", "display_name": "Digital Commons (Liberty University)", "issn_l": null, "issn": null, "is_oa": false, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I67789559", "host_organization_name": "Liberty University", "host_organization_lineage": ["https://openalex.org/I67789559"], "host_organization_lineage_names": [], "type": "repository"}, "license": "public-domain", "license_id": "https://openalex.org/licenses/public-domain", "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": "Doctoral Dissertations and Projects", "raw_type": "text"}, "abstract": "The purpose of this qualitative multiple case study was to explore how organizational leaders navigate high-stakes crises, with a focus on cognitive, emotional, and crisis response leadership processes, as well as decision-making, and organizational factors that influence outcomes. Grounded in a pragmatic research paradigm, this study explored the experiences of leaders across multiple industries that frequently encounter high-stakes crisis events. Research data was collected through semi-structured interviews and analyzed using thematic analysis to identify patterns and key themes. The findings revealed that crisis leadership is a dynamic and iterative process characterized by cognitive processing, emotional regulation, crisis response behaviors, and experience-based decision-making. Leaders consistently relied on prior experience to interpret evolving situations, regulate emotional responses, and make timely decisions under conditions of urgency and uncertainty. Communication emerged as a critical mechanism for coordinating team efforts, while effective leadership approaches emphasized adaptability, collaboration, and the ability to maintain composure in high-stress environments. This study contributes to the body of knowledge by providing an integrated, practice-oriented understanding of crisis leadership that extends beyond traditional command-and-control models. The findings offer practical insights for leadership development, training, and organizational preparedness, while advancing theoretical perspectives on leadership as an iterative, experience-driven process. These results provide a foundation for future research and support the development of more effective leadership strategies in high-stakes crisis environments."}]", "excerpt_truncated": true, "source_sha256": "8f9250099ce7df58b1e1409b170e8bc88327c4a052b5f1a6a2b38cb4f02549f2", "verification_required": true, "topic_domain": "judgment_and_consensus", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.18653/v1/2025.emnlp-main.1562", "openalex:W4416035436"], "source_candidates": ["https://doi.org/10.18653/v1/2025.emnlp-main.1562", "https://aclanthology.org/2025.emnlp-main.1562.pdf"], "source_candidate_identities": {}}

